		/// <summary>
		/// Creates a window that is initially visible.
		/// </summary>
		WS_VISIBLE = 0x10000000,
		/// <summary>
		/// Creates a window that is initially disabled. 
		/// A disabled window cannot receive input from the user
		/// </summary>
		WS_DISABLED = 0x08000000,
